const engines=['ANALOG','—','PHASE','LOFI','SAMPLE','VOICE','TRIO','WHEEL','GRAIN','PHYS','DRUM','NOISE','FM6','SLICE'];
const scales=['Chromatisch','Dur','Moll','Dorian','Mixolydian','Pent. Dur','Pent. Moll','Harm. Moll','Phrygian','Lydian','Locrian','Mel. Moll','Blues','Ganzton','Dim H–W','Dim W–H','Hirajoshi','Insen','Iwato','Kumoi','Egyptian','Ryukyu','Hungarian','Phryg. dominant','Lydian dominant','Dorian ♭2','Neapolitan','Augmented','Prometheus','Tritone','Harm. Dur','Enigmatic'];
const notes=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'];
const audio=new Audio();let playing=-1;let data;
function state(){document.querySelectorAll('.world').forEach((el,i)=>{el.classList.toggle('playing',playing===i);el.querySelector('button').textContent=playing===i?'Ⅱ':'▶';el.querySelector('button').setAttribute('aria-pressed',String(playing===i));});}
audio.addEventListener('ended',()=>{playing=-1;state();});audio.addEventListener('error',()=>{playing=-1;state();document.getElementById('audioStatus').textContent='Preview could not be loaded. Please try again.';});
function sounds(role){const box=document.getElementById('sounds');box.replaceChildren();for(const [i,s] of data.banks[role].entries()){const e=document.createElement('div');e.className='sound';const b=document.createElement('b');b.textContent=String(i+1).padStart(2,'0')+' / '+s[0];const sub=document.createElement('span');sub.textContent=engines[s[1]];e.append(b,sub);box.append(e);}}
document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-role]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));if(data)sounds(Number(b.dataset.role));});
try{const r=await fetch('library.json');if(!r.ok)throw Error();data=await r.json();const box=document.getElementById('worlds');data.worlds.forEach((w,i)=>{const row=document.createElement('div');row.className='world';const text=document.createElement('div'),name=document.createElement('b'),meta=document.createElement('small'),play=document.createElement('button');name.textContent=String(i+1).padStart(2,'0')+' / '+w[0];meta.textContent=notes[w[3]]+' '+scales[w[4]]+' · '+w[5]+' BPM';text.append(name,meta);play.textContent='▶';play.setAttribute('aria-label',w[0]+' — play preview');play.setAttribute('aria-pressed','false');play.onclick=async()=>{if(playing===i){audio.pause();playing=-1;state();return;}document.querySelector('video')?.pause?.();audio.pause();playing=i;audio.src='audio/world-'+String(i).padStart(2,'0')+'.mp3';state();document.getElementById('audioStatus').textContent=w[0]+' · Firmware audio · 16 seconds';try{await audio.play();}catch{playing=-1;state();document.getElementById('audioStatus').textContent='Playback was blocked. Press play again.';}};row.append(text,play);box.append(row);});sounds(0);}catch{document.getElementById('audioStatus').textContent='The sound library could not be loaded. Reload the page.';}

// Listening previews and the narrated film never play over each other.
document.querySelector('video')?.addEventListener('play',()=>{audio.pause();playing=-1;state();});
